const FONT_NAMES = {
  regular: 'Inter-Regular',
  medium: 'Inter-Medium',
  semibold: 'Inter-SemiBold',
  bold: 'Inter-Bold'
} as const;

const FALLBACK_FONTS: ReportFonts = {
  regular: 'Helvetica',
  medium: 'Helvetica',
  semibold: 'Helvetica-Bold',
  bold: 'Helvetica-Bold'
};

let cachedBuffers: { regular?: Buffer; medium?: Buffer; semibold?: Buffer; bold?: Buffer } = {};

function decodeBase64ToBuffer(base64Text: string): Buffer | undefined {
  try {
    return Buffer.from(base64Text, 'base64');
  } catch {
    return undefined;
  }
}

function getFontBuffer(kind: keyof ReportFonts): Buffer | undefined {
  const cached = cachedBuffers[kind];
  if (cached) {
    return cached;
  }

  const source =
    kind === 'regular'
      ? INTER_400_REGULAR_WOFF_BASE64
      : kind === 'medium'
        ? INTER_500_MEDIUM_WOFF_BASE64
        : kind === 'semibold'
          ? INTER_600_SEMIBOLD_WOFF_BASE64
          : INTER_700_BOLD_WOFF_BASE64;

  const decoded = decodeBase64ToBuffer(source);
  if (!decoded) {
    return undefined;
  }
  cachedBuffers = { ...cachedBuffers, [kind]: decoded };
  return decoded;
}

function registerFontBuffer(doc: PDFKit.PDFDocument, name: string, buffer: Buffer | undefined): boolean {
  if (!buffer) {
    return false;
  }

  try {
    doc.registerFont(name, buffer);
    return true;
  } catch {
    return false;
  }
}

export function registerReportFonts(doc: PDFKit.PDFDocument): ReportFonts {
  const regular = registerFontBuffer(doc, FONT_NAMES.regular, getFontBuffer('regular'));
  const medium = registerFontBuffer(doc, FONT_NAMES.medium, getFontBuffer('medium'));
  const semibold = registerFontBuffer(doc, FONT_NAMES.semibold, getFontBuffer('semibold'));
  const bold = registerFontBuffer(doc, FONT_NAMES.bold, getFontBuffer('bold'));

  return {
    regular: regular ? FONT_NAMES.regular : FALLBACK_FONTS.regular,
    medium: medium ? FONT_NAMES.medium : FALLBACK_FONTS.medium,
    semibold: semibold ? FONT_NAMES.semibold : FALLBACK_FONTS.semibold,
    bold: bold ? FONT_NAMES.bold : FALLBACK_FONTS.bold
  };
}
